  "spanish": "Elena y Marta se conocieron en un curso de cocina. Hace cuatro años que son amigas. Antes se veían todas las semanas porque estudiaban en el mismo centro. Ahora Elena trabaja por las tardes y Marta tiene otro horario. Ya no pueden cocinar juntas cada viernes, pero todavía hablan por teléfono. Este mes han preparado una cena en casa de Elena. Marta llevó la receta que usaban en clase y Elena cambió algunos ingredientes. Mientras cocinaban, hablaron de sus nuevas rutinas. No querían recuperar exactamente el pasado: buscaban una forma de seguir viéndose. Al final decidieron quedar una vez al mes. La frecuencia cambió, pero las dos seguían interesadas en cuidar la amistad.",
