  "explanation": "A future commitment is credible when its action and timing are clear.",
  "spanish": "Diego prometió enviar a Luis una receta, pero olvidó hacerlo. Cuando Luis preguntó de nuevo, Diego no respondió con una promesa enorme. Dijo: «La buscaré esta tarde y te la enviaré antes de las seis». Tenía el cuaderno en casa y sabía que podría consultarlo después del trabajo. Luis iba a cocinar al día siguiente, así que ese plazo era suficiente. Ana sugirió hacer una foto para no copiar toda la receta. Diego lo hizo y añadió una nota sobre una cantidad que podía confundir. Al final Luis recibió la información a tiempo. La promesa fue útil porque incluía una acción concreta y un límite realista, no solo una buena intención.",
