  "spanish": "Diego tiene que preparar una presentación y no sabe por dónde empezar. Ha escrito muchas notas, pero no ha elegido las ideas principales. Elena le sugiere dividir el trabajo en tres partes. Primero podría explicar el problema; después mostrar un ejemplo; al final proponer una solución. No hace falta contar todos los detalles que conoce. Diego teme olvidar algo importante. Elena le recomienda ensayar con un compañero y pedir preguntas al final. Él prepara una versión más corta y descubre que puede explicarla sin leer cada palabra. No ha aprendido menos: ha organizado mejor lo que sabe. El consejo trata de claridad, no de hablar más rápido para incluirlo todo.",
