  "explanation": "A reaction is personal; explain it without turning disagreement into conflict.",
  "spanish": "Clara invitó a sus amigos a un restaurante nuevo. A Marta le encantó la sopa, pero a Luis le pareció demasiado salada. Ana valoró que el camarero explicara los ingredientes con paciencia. Diego estaba preocupado por el precio, aunque al final la cuenta fue menor de lo esperado. Al comentar la cena, separaron comida, atención y coste. Clara no se sintió atacada porque alguien no disfrutó de un plato. Explicó que quería conocer el lugar y no garantizar una experiencia perfecta. Todos lo pasaron bien conversando. Decidieron que podían repetir otra vez y elegir platos diferentes. La conversación mostró que una experiencia compartida puede producir reacciones distintas sin estropear la relación.",
