  "language": "en-or-es",
  "explanation": "A changed itinerary need not mean a failed visit.",
  "spanish": "Clara iba a visitar a su hermana durante el fin de semana. El tren del viernes se retrasó y perdió una conexión. Primero se preocupó porque su hermana esperaba en la estación. Después la llamó y buscó otra opción. Podía tomar un autobús, aunque llegaría más tarde. Su hermana propuso recogerla en otra parada. Clara aceptó y confirmó la nueva hora. El sábado caminaron y cocinaron juntas. El viaje no fue como pensaba, pero lo pasó muy bien. Al volver, explicó que la comunicación fue más importante que mantener el horario inicial. La próxima vez dejará más tiempo entre conexiones. No cree que eso elimine todos los problemas, pero sí puede reducir una dificultad previsible.",
