  "spanish": "Marta y Ana prepararon un taller para vecinos nuevos. Antes Marta hacía casi todo sola y terminaba agotada. Esta vez pidió ayuda desde el principio. Ana escribió el mensaje de invitación y Luis organizó el espacio. El día del taller hubo más gente de la prevista. Primero movieron algunas sillas y después dividieron el grupo en dos. A Marta le sorprendió que los participantes también ofrecieran soluciones. Al final varias personas propusieron otra sesión. Marta explicó que todavía hubo momentos de confusión, pero ya no sentía que todo dependía de ella. Quiere mantener esa forma de trabajar. La próxima semana hablará con el grupo para decidir un tema, en lugar de elegirlo sin escuchar.",
