  "language": "en-or-es",
  "explanation": "Connected communication includes responding to other accounts, not only telling your own.",
  "spanish": "El domingo Ana, Luis y Diego hablaron de sus semanas. Ana contó una visita agradable; Luis explicó un retraso y Diego una presentación difícil. No compitieron por decidir quién tuvo la semana peor. Primero escucharon lo ocurrido y después preguntaron qué ayudó en cada caso. Ana disfrutó porque no llenó todo el día de planes. Luis llamó cuando cambió el horario. Diego pidió comentarios y acortó su presentación. Cada uno encontró una idea útil en la experiencia de otro. Al final acordaron una salida sencilla para la semana siguiente. Todavía no eligieron el lugar, pero fijaron una hora para hablar. El encuentro transformó tres relatos individuales en una conversación con preguntas, razones y propuestas.",
