  "explanation": "Distinguish a personal interpretation from evidence of another person’s feelings.",
  "spanish": "Marta escribió a Elena para cambiar una cena. Elena respondió solo «vale». Marta pensó que estaba enfadada porque normalmente añadía una pregunta o un comentario. Durante dos días no volvió a escribir. Elena, por su parte, esperaba la nueva hora y no entendía el silencio. Cuando se encontraron, descubrieron que Elena respondió deprisa entre dos reuniones. No estaba molesta con la propuesta. Marta reconoció que interpretó una palabra sin comprobar el contexto. Elena admitió que podía haber añadido «dime la nueva hora». Las dos se llevan bien, pero no leen los mensajes de la misma forma. Acordaron preguntar antes de sacar conclusiones. No prometieron estar siempre disponibles: buscaron una manera de distinguir un retraso normal de algo que necesitan aclarar.",
