  "language": "en-or-es",
  "explanation": "Constructive repair acknowledges the specific effect and changes future action.",
  "spanish": "Diego publicó una foto de una cena sin preguntar a quienes aparecían. Elena le pidió quitarla porque no quería una imagen suya en una página pública. Diego se sorprendió: pensaba que era una manera de agradecer la visita. Elena explicó que apreciaba la cena, pero prefería decidir qué imágenes comparte. Diego retiró la foto y pidió disculpas. Después preguntó si podía publicar una foto solo de los platos. Elena aceptó. No tuvieron que discutir si todas las fotos son buenas o malas. El punto era respetar una preferencia concreta y preguntar antes. Diego entendió que una buena intención no elimina el efecto que una acción tiene en otra persona. La próxima vez pedirá permiso sin esperar a que alguien proteste.",
