  "spanish": "Elena recibe un proyecto de Diego y escribe que está bien. Diego se alegra, pero no sabe qué mantener ni qué cambiar. Le pide un ejemplo de una parte clara y otra que necesita trabajo. Elena señala una explicación breve que funciona y una conclusión que repite datos sin responder a la pregunta. Diego revisa la conclusión y entrega una segunda versión. No pide que Elena escriba por él; busca información para decidir. Elena también aprende a dar comentarios más concretos. En la siguiente reunión preguntan qué tipo de ayuda necesita cada compañero. El intercambio muestra que pedir orientación no significa dejar de ser responsable del propio trabajo. Una valoración positiva puede animar, pero un ejemplo específico permite mejorar.",
