  "explanation": "Accuracy depends on context and time, not only whether an event once happened.",
  "spanish": "Luis recibió en un grupo una noticia sobre el cierre de una estación. El mensaje no incluía fecha y una imagen parecía oficial. Estaba a punto de compartirlo cuando Ana preguntó dónde se publicó. Buscaron la información en la página de la empresa. El cierre fue el año anterior y la estación ya estaba abierta. Luis explicó al grupo la diferencia y añadió la fecha correcta. No se limitó a decir que todo era falso: la imagen describía un hecho real, pero antiguo. La experiencia le enseñó a comprobar origen y tiempo antes de usar una noticia para tomar decisiones. Ana recordó que una fuente conocida tampoco elimina la necesidad de leer los detalles relevantes para el viaje actual.",
