  "explanation": "A useful instruction is actionable and honest about limits.",
  "spanish": "Diego estaba escribiendo un documento cuando la aplicación dejó de responder. Cerró la ventana y al volver vio una versión anterior. Se preocupó porque pensó que todo estaba perdido. Elena le pidió comprobar las copias guardadas y la hora de la última actualización. Encontraron una copia automática con casi todo el trabajo. Diego recuperó el texto y escribió de nuevo un párrafo corto. Después activó una forma de guardar versiones con nombres claros. Elena no aseguró que nunca volvería a fallar. Explicó qué paso redujo el riesgo y qué información necesitó para buscar la copia. El problema se resolvió sin culpar a Diego por no conocer cada función de la aplicación.",
