  "spanish": "Clara llama a sus padres por vídeo cada domingo. A su padre le cuesta encontrar el botón para entrar. Antes Clara repetía las instrucciones más rápido porque pensaba que así terminarían antes. Ahora pregunta qué ve en la pantalla y explica un paso cada vez. Su madre escribió una lista corta que dejan junto al ordenador. La próxima llamada empieza sin ayuda. Clara se alegra, pero no concluye que sus padres ya conocen todas las funciones. Ellos quieren hablar con la familia, no aprender cada herramienta disponible. La tecnología facilita una conversación importante cuando las instrucciones se adaptan a la persona. Un mensaje largo con palabras técnicas habría sido menos útil que dos pasos claros y una comprobación.",
