  "language": "en-or-es",
  "explanation": "Weigh benefits and limits without turning one experiment into a universal rule.",
  "spanish": "Ana nota que mira el móvil incluso mientras conversa. No quiere dejar de usarlo: le sirve para orientarse y mantener contacto con amigos. Decide probar un límite durante las comidas. Luis teme que no vea un mensaje urgente. Ana explica que puede avisar a su familia y revisar el teléfono después. La primera semana no es perfecta; algunas veces lo mira sin pensar. En vez de presentar el cambio como un fracaso, observa cuándo ocurre y deja el móvil fuera de la mesa. Descubre que escucha mejor sin perder el contacto con otras personas. No recomienda el mismo límite para todos: Diego trabaja con pedidos y necesita atender ciertos avisos. Hablan de necesidades distintas, no de una regla moral única.",
