  "spanish": "Marta tiene una molestia en la espalda y prepara una consulta. Ana le propone escribir cuándo empezó, qué estaba haciendo y cómo ha cambiado. Marta añade que le cuesta moverse por la mañana, pero mejora algo después. No busca una lista de enfermedades en mensajes del grupo. Quiere explicar su situación con claridad al profesional. También anota una pregunta sobre sus actividades habituales. Ana no recomienda un tratamiento ni asegura que sea un problema pequeño. La ayuda consiste en organizar la información y acompañarla si lo necesita. Marta se siente más tranquila porque sabe qué contar, no porque alguien haya prometido una solución antes de escucharla. En la consulta podrá preguntar cuando no entienda una indicación.",
