  "spanish": "Diego quiere dormir mejor. Trabaja algunos días hasta tarde y antes intentaba levantarse siempre muy temprano para estudiar. Esta semana ha dormido poco y nota cansancio. Elena le sugiere revisar el horario y buscar una rutina posible, no copiar la de otra persona. Diego decide estudiar menos tiempo después de un turno largo y preparar tareas en una mañana libre. No espera cambiar todo en un día. También reconoce que, si el problema continúa, necesitará consejo profesional. Al comentar su plan, explica qué depende de él y qué no puede modificar ahora. La conversación no convierte el cansancio en un fallo personal. Busca un ajuste práctico y deja espacio para pedir ayuda cuando sea necesario.",
