  "spanish": "Luis entra en la farmacia porque no entiende una indicación de un producto que ya tiene. Lleva el envase y explica qué le preocupa. La farmacéutica le pregunta si la duda es sobre la cantidad, el horario o una advertencia. Luis señala la frase concreta y pide una explicación más sencilla. No compra otro producto solo porque un amigo lo recomienda. La farmacéutica aclara la información y le indica cuándo debe consultar con un profesional sanitario. Luis repite lo entendido para comprobarlo. Al salir no dice que domina todos los detalles; conserva la información escrita y sabe dónde preguntar de nuevo. La interacción muestra cómo usar el idioma para evitar una suposición cuando una instrucción afecta a la salud.",
