  "explanation": "A sustainable shared activity can respect different needs without medical promises.",
  "spanish": "Clara y Ana empiezan a caminar juntas dos tardes por semana. Clara quiere recorrer más distancia cada día, mientras Ana necesita un ritmo más suave. Al principio Ana siente que debe seguirla para no decepcionarla. Después explica que quiere disfrutar y mantener una rutina, no competir. Clara escucha y acuerdan un camino con opciones más cortas. Algunos días Clara continúa sola y otros vuelven juntas. No presentan caminar como una solución para cualquier problema de salud. Es una actividad que les gusta y que pueden adaptar. Ana valora poder expresar un límite sin perder la compañía. El acuerdo dura porque no depende de que las dos tengan siempre la misma energía ni los mismos objetivos.",
