  "language": "en-or-es",
  "explanation": "Describe the observed event and its limits before drawing a wider conclusion.",
  "spanish": "Ana visita un pueblo durante una fiesta local. Ve que algunas tiendas cierran antes y piensa que nadie trabaja por la tarde. Clara le explica que ese día hay un horario especial y que otras semanas es distinto. Ana cambia su descripción: en lugar de hablar de todo el pueblo, cuenta lo que observó durante la fiesta. Pregunta por la celebración y escucha dos historias diferentes de vecinos. No intenta decidir una regla única a partir de una tarde. Al volver, recomienda visitar el lugar, pero aconseja comprobar los horarios. La experiencia le enseña que una observación cultural gana valor cuando incluye su contexto. Puede contar algo interesante sin convertirlo en una afirmación sobre todas las personas de una región.",
