  "spanish": "Diego reservó una visita guiada por un barrio histórico. Esperaba caminar mucho, pero el guía dedicó tiempo a escuchar recuerdos de una vecina. Al principio Diego miraba el reloj. Después comprendió por qué una calle cambió de nombre y cómo se usaba una antigua tienda. La visita fue más lenta de lo esperado, aunque le pareció más interesante. Ana prefería ver más edificios y comentó esa diferencia con respeto. El guía explicó que existían rutas con otro enfoque. Los dos entendieron que no necesitaban valorar la experiencia de forma idéntica. Al recomendarla, Diego habló del ritmo y de las historias para que otros pudieran elegir. No ocultó lo que podría ser una desventaja para alguien con poco tiempo.",
