  "spanish": "Marta compara una excursión organizada con viajar por su cuenta. La primera incluye transporte y una guía; la segunda permite quedarse más tiempo en cada lugar. El precio no es muy diferente. Marta pregunta qué pasa si cambia el horario y cuánto tiempo libre ofrece la excursión. Luis viajó con esa empresa una vez y cuenta una experiencia positiva, pero recuerda que fue en otra temporada. Marta no usa esa anécdota como garantía. Elige viajar por su cuenta porque quiere visitar a una amiga además del museo. Agradece la recomendación y explica su motivo. La decisión no significa que la excursión sea mala. Significa que una opción útil para Luis no responde del todo a lo que Marta quiere hacer esta vez.",
