  "spanish": "Ana y Marta hablan de qué harían con una tarde completamente libre. Ana iría al museo y después caminaría sin mirar el reloj. Marta cocinaría con su familia. No están acordando una salida concreta: comparan deseos con sus rutinas actuales. Ana reconoce que podría reservar una hora el domingo, aunque no toda la tarde. Marta piensa que no hace falta esperar una semana perfecta para preparar una cena sencilla. Las dos distinguen imaginar de prometer. El ejercicio les ayuda a encontrar un cambio pequeño que sí pueden probar. Al terminar acuerdan llamar el domingo para ver cómo fue. No aseguran que el trabajo desaparecerá; buscan espacio dentro de sus condiciones reales.",
