  "language": "en-or-es",
  "explanation": "Desired consequences are hypothetical until relevant conditions are checked.",
  "spanish": "Luis ve un piso cerca de su trabajo y piensa que su vida sería más fácil allí. Tendría menos trayecto y podría volver a casa a comer. Sin embargo, el alquiler es mayor y perdería la cercanía de sus amigos. Ana le ayuda a comparar sin decidir por él. Hablan primero de una semana normal y después de los gastos. Luis no confunde «me gustaría» con «puedo pagarlo». Decide visitar el piso y preguntar por las condiciones antes de hacer una oferta. La posibilidad sigue abierta. La conversación le permite explicar ventajas y costes de una vida imaginada, pero la decisión necesita datos. Al final no anuncia una mudanza: dice qué va a comprobar y por qué.",
