  "explanation": "Conditional language makes a proposal useful without overstating available resources.",
  "spanish": "Elena quiere organizar un club de conversación. Con una sala disponible podría reunir a vecinos una tarde por semana. Diego ofrecería bebidas del café, pero no puede pagar todo el material. Clara ayudaría con la invitación. Antes de anunciarlo hablan de lo que cada uno realmente puede aportar. El entusiasmo no garantiza que tengan espacio ni participantes. Elena pide información al centro cultural y pregunta si otras actividades usan la sala. No cancela la idea por no tener todo resuelto. La convierte en una propuesta con condiciones claras. El grupo decide empezar con una sesión de prueba si consigue el espacio. Así puede aprender de la experiencia antes de prometer un programa completo.",
