  "spanish": "Elena consigue una nueva oportunidad de trabajo. Clara le escribe que se alegra de la noticia y espera que tenga tiempo para descansar antes de empezar. Elena responde que está contenta y algo nerviosa. Todavía debe conocer al equipo y entender cómo se reparten las tareas. Clara no asegura que todo será fácil. Dice que es importante que pregunte cuando una instrucción no esté clara. Elena agradece una reacción que combina alegría y apoyo práctico. También explica qué necesita ahora: no quiere consejos sobre cada decisión, sino hablar de cómo organizar la primera semana. Clara escucha y cambia su propuesta. La conversación muestra que expresar una emoción por otra persona puede abrir espacio para escuchar, no solo para celebrar.",
