  "spanish": "El grupo de vecinos debe elegir una actividad para el mes siguiente. Luis quiere una excursión y Ana prefiere un taller. Algunas personas no conocen el coste ni el tiempo necesario. Elena propone escuchar las dos opciones antes de votar. «Es importante que todos tengamos la misma información», explica. Luis presenta el precio y la duración. Ana describe el espacio y los materiales. Después aparecen preguntas que ninguno esperaba. No cambian cada propuesta para gustar a todos; aclaran lo necesario para comparar. Al final el grupo decide empezar con el taller y preparar la excursión más adelante. Luis sigue prefiriendo salir, pero reconoce que la decisión tuvo un proceso más justo. Su deseo no desaparece, aunque acepta el resultado.",
