  "language": "en-or-es",
  "explanation": "Present subjunctive expresses the wished-for experience without certifying the outcome.",
  "spanish": "Ana escribe a su hermana antes de una visita. Quiere que llegue sin preocuparse por organizar cada detalle. Le dice que espera que tenga un viaje tranquilo y que le alegra que puedan pasar el fin de semana juntas. También pide que envíe la hora de llegada cuando la conozca. Su hermana responde que prefiere decidir algunas actividades después de descansar. Ana acepta y cambia un plan demasiado lleno. No confunde desear una visita agradable con controlar lo que hará la otra persona. Deja una comida confirmada y el resto abierto. El mensaje final incluye afecto, una petición necesaria y libertad para ajustar el fin de semana. Es más útil que una lista de obligaciones disfrazada de bienvenida.",
