  "explanation": "An example supports a proposal; a bounded trial tests it.",
  "spanish": "Diego propone un taller de cocina para vecinos. Luis teme que cueste demasiado y que pocas personas participen. Diego escucha la preocupación y evita responder solo que será divertido. Cuenta que el año pasado organizó una cena pequeña y varias personas pidieron aprender la receta. Esa experiencia apoya la idea, pero no prueba que todos asistirán. Ana propone una sesión corta con inscripción previa. Así pueden conocer el interés antes de comprar muchos materiales. Luis acepta la prueba porque reduce un riesgo concreto. El grupo acuerda revisar los comentarios después. La conversación termina con una decisión limitada y comprobable, no con una promesa de éxito. Diego mantiene su propuesta, pero la mejora al responder a una objeción real.",
