  "spanish": "Elena vive sobre un local donde hay música algunas noches. Quiere pedir un cambio, pero no desea que desaparezca toda actividad del barrio. Luis le aconseja describir horarios y efectos concretos. Elena explica que después de cierta hora no puede dormir. El encargado responde que algunos clientes trabajan tarde y solo pueden ir por la noche. Elena reconoce esa necesidad, pero pide bajar el volumen y cerrar la puerta. Propone revisar el resultado durante dos semanas. El encargado acepta probarlo. El acuerdo no elimina intereses diferentes. Busca una forma de reducir el efecto más molesto y comprobar si basta. Elena aprende que defender su necesidad con precisión puede abrir más opciones que exigir una solución total sin escuchar.",
