  "language": "en-or-es",
  "explanation": "A communicative success can be a revised shared plan rather than an unchanged personal idea.",
  "spanish": "Ana quería organizar una salida de todo un día. Marta explicó que varias personas solo podían venir por la mañana y Diego preguntó por el coste. Ana recordó una excursión anterior, pero esta vez el grupo tenía otras condiciones. En lugar de repetir su primer plan, propuso un paseo corto con una comida opcional. Quienes necesitaban volver podían hacerlo sin perder toda la actividad. Luis sugirió enviar dos horarios claros y Ana aceptó. Al final el mensaje no se parecía exactamente al borrador inicial, aunque mantenía su objetivo: pasar tiempo juntos. La discusión no fue un fracaso de la propuesta. Fue la manera de convertir una idea personal en un plan compartido. Todos sabían qué estaba acordado y qué seguía siendo opcional.",
