  "explanation": "An understandable reason does not erase its impact on another person.",
  "spanish": "Clara llamó a Marta para explicar por qué canceló una visita. El día anterior había confirmado el horario y comprado el billete. Por la mañana recibió una llamada de su hermana, que necesitaba ayuda con una mudanza inesperada. Clara primero buscó una forma de mantener ambas cosas. Cuando vio que no podía, avisó a Marta y propuso otra fecha. Marta estaba decepcionada porque había preparado una comida especial. No pensó que la necesidad de Clara fuera falsa, pero le costó aceptar el cambio. Durante la conversación distinguieron dos planos: el motivo de cancelar y el efecto sobre la otra persona. Clara pidió disculpas sin prometer que nunca volvería a cambiar un plan. Marta explicó su reacción sin exigir que Clara ignorara a su hermana. La visita quedó para otro día y las dos entendieron mejor qué hizo difícil aquella llamada.",
