  "language": "en-or-es",
  "explanation": "Source attribution and chronology guard against an overconfident interpretation.",
  "spanish": "Luis vio un vídeo corto de una discusión en una estación. Parecía mostrar a una empleada negándose a ayudar a un viajero. Una noticia más larga explicaba que antes se había ofrecido otra conexión y que el viajero no aceptó el horario. Esa información no demostraba que la empleada actuara perfectamente, pero cambiaba la interpretación de su respuesta. Ana señaló que el vídeo empezaba después de la propuesta y no mostraba el intercambio completo. Los dos compararon lo visible con lo que solo afirmaba la noticia. No decidieron quién tenía toda la razón. Prepararon un resumen que indicaba qué se veía y qué se decía sobre el contexto anterior. Luis entendió que una narración breve puede ser verdadera en sus imágenes y aun así incompleta. La conclusión prudente fue pedir más contexto antes de compartir una acusación.",
