  "language": "en-or-es",
  "explanation": "A cause chain distinguishes an initial event from modifiable consequences.",
  "spanish": "Diego debía llegar a un taller en otra ciudad. Una avería retrasó su primer tren y perdió la conexión. Debido a ese cambio llegó una hora tarde. El centro empezó la actividad sin él y adaptó el orden: Ana presentó los materiales mientras Luis atendía las preguntas. Diego avisó en cuanto tuvo una nueva hora de llegada. El retraso produjo dificultades, pero la información permitió reducirlas. Al terminar, el grupo distinguió la causa inicial de las consecuencias que podía controlar. No podían reparar el tren, pero sí reorganizar la sesión y avisar a quienes esperaban. Diego preparó después un mensaje con las fechas y el justificante del retraso. Explicar la cadena no significaba excusarse de todo. También reconoció qué hizo para ayudar y qué habría sido útil preparar antes del viaje, como dejar los materiales accesibles al grupo.",
