  "explanation": "A disappointing result supports questions, not an unbounded causal rule.",
  "spanish": "Marta bajó el precio de una actividad y esperaba que asistiera más gente. La siguiente sesión tuvo pocos participantes. Algunos concluyeron que el precio no importa. Ana señaló que ese día llovió mucho y coincidió con otra actividad del barrio. Marta también descubrió que el anuncio llegó tarde a varias personas. No usaron esos factores para afirmar lo contrario con la misma seguridad. Prepararon una nueva sesión con el mismo precio, una fecha distinta y más tiempo para avisar. Sabían que una prueba pequeña no aislaría todos los efectos, pero podía dar información útil. La conversación evitó dos errores: declarar que el precio siempre decide la asistencia o que nunca influye. En ambos casos se habría convertido un resultado limitado en una regla. Marta decidió describir lo observado y explicar qué quería comprobar después.",
