  "spanish": "Ana llega al centro y encuentra las luces apagadas. Piensa que quizá estaba cancelada la reunión. Luis cree que quizá cambiaron de sala, pero no tiene una confirmación. Clara recuerda que el edificio cierra una entrada temprano y propone mirar la otra. Nadie afirma conocer la causa solo por ver oscuridad. Encuentran un aviso que indica el nuevo acceso y el horario de la sesión. La reunión sigue prevista. Ana distingue su primera impresión de la información confirmada. Luis reconoce que su hipótesis sobre la sala no era exactamente la solución. Las posibilidades ayudaron a pensar en próximos pasos, pero necesitaban una comprobación. Al contar lo ocurrido, Ana no dice «la reunión estaba cancelada». Explica que lo pensó al principio y después encontró información distinta. La diferencia evita transmitir a otros una conclusión que ya sabe que no era correcta.",
