  "prompt": "Explain the reason using a short English or Spanish response.",
  "promptEs": "¿Por qué necesita información?",
  "englishHint": "Explain the reason using a short English or Spanish response.",
  "answer": "Para organizar sus turnos.",
  "accepted": [
   "Para organizar sus turnos.",
   "To organise his work shifts."
  ],
  "language": "en-or-es",
  "explanation": "Uncertainty can support conditional planning rather than misinformation.",
  "spanish": "Diego oye que el curso cambiará de día. Una compañera lo leyó en un mensaje de otro grupo y dice que probablemente sea cierto. Diego necesita organizar sus turnos, pero no toma el rumor como un horario oficial. Pregunta al centro y recibe una respuesta: están considerando el cambio, sin decisión final. Diego informa al grupo con esa misma distinción. No escribe que el horario ya ha cambiado. Elena agradece que no transforme una posibilidad en una noticia segura. El centro promete avisar antes del viernes. Mientras tanto, Diego prepara dos opciones de trabajo. La incertidumbre no le obliga a quedarse sin hacer nada, pero tampoco justifica actuar como si la decisión estuviera tomada. El relato muestra cómo una comunicación cauta puede permitir planificación sin inventar una certeza.",
