  "explanation": "Emotional truth is not proof of a specific explanation.",
  "spanish": "Marta ve que una amiga no responde desde la mañana. Piensa que puede estar enfadada por una conversación anterior. Ana propone otra posibilidad: quizá tenga un día ocupado. Ninguna conoce el motivo. Marta decide enviar una pregunta breve y no una acusación. Más tarde la amiga explica que perdió el móvil durante varias horas. Esa respuesta aclara el caso, pero no demuestra que todas las ausencias de respuesta tengan el mismo motivo. Marta aprende a elegir lenguaje proporcional a lo que sabe. Puede decir «me preocupó no saber de ti» sin afirmar «sé que estabas enfadada». Su emoción es real aunque su explicación fuera equivocada. Al separar ambas cosas, la conversación resulta más fácil y no obliga a la amiga a defenderse de una intención que nunca tuvo.",
