  "language": "en-or-es",
  "explanation": "Probabilities, verified conditions and agreements serve different roles.",
  "spanish": "Clara prepara una salida y ve una previsión de lluvia. Dice que probablemente necesitarán una ruta más corta. Luis interpreta que la excursión está cancelada. Clara aclara que la lluvia es una posibilidad y que todavía pueden adaptar el recorrido. Es posible que algunos caminos no estén disponibles, así que van a consultar la información local antes de salir. No usarán una previsión general para asegurar el estado de cada camino. El grupo acuerda dos opciones y una hora para confirmar. Ana valora saber qué está decidido: la reunión del grupo. Lo pendiente es la ruta. La conversación mantiene una diferencia entre probabilidad, condición práctica y acuerdo. Al final nadie promete buen tiempo ni una cancelación inevitable. Tienen un plan para comprobar lo relevante y comunicar la decisión a tiempo.",
