  "spanish": "Ana cuenta que un nuevo carril de bicicleta le facilita llegar al trabajo. Diego pregunta si eso demuestra que todos los comercios se benefician. Ana reconoce que habla de su trayecto y no tiene datos sobre ventas. Marta conoce una tienda que tuvo dificultades durante las obras. Los tres separan efectos temporales de cambios posteriores. No niegan la utilidad del carril porque una tienda sufrió molestias, ni descartan esas molestias porque Ana está contenta. Proponen preguntar a vecinos y comerciantes después de un periodo suficiente. La conversación muestra que defender una mejora incluye reconocer costes y buscar información sobre grupos distintos. Ana mantiene su valoración personal, pero cambia una frase demasiado amplia. En vez de decir «todo el barrio ha ganado», explica qué mejoró para ella y qué consecuencias aún deben comprobar.",
