  "explanation": "A firm formal complaint separates observed facts from inferred motives.",
  "spanish": "Marta recibió una chaqueta de talla pequeña aunque el pedido indicaba mediana. Su primer mensaje expresaba enfado, pero no incluía el número de compra. Ana le propuso distinguir lo ocurrido, la evidencia y la solución solicitada. Marta adjuntó una foto de la etiqueta y copió los datos del pedido. Escribió que quería un cambio por la talla correcta y preguntó cómo devolver el producto recibido. No afirmó que la empresa quisiera engañarla: no conocía la causa del error. El servicio respondió con un procedimiento y un plazo. Marta pidió confirmar si había algún coste adicional. La reclamación no perdió firmeza por mantener un tono cortés. Ganó claridad porque la persona que la recibió podía identificar el caso y responder a una petición específica. Al final Marta guardó el intercambio hasta recibir la nueva chaqueta.",
