  "language": "en-or-es",
  "explanation": "A follow-up can preserve politeness while making an unanswered requirement explicit.",
  "spanish": "Luis quiere contratar una actividad para un grupo. La página anuncia un precio, pero no indica si incluye materiales ni qué ocurre con una cancelación. Escribe una consulta breve con el número de participantes y dos preguntas. El centro responde sobre el precio, pero omite la condición de cancelación. Luis agradece la información y vuelve a preguntar por ese punto. No trata la primera respuesta incompleta como una negativa. Tampoco paga antes de conocer un detalle importante para el grupo. Elena revisa el mensaje y recomienda mantener las preguntas separadas para facilitar la respuesta. Cuando llega la confirmación final, Luis resume las condiciones a sus compañeros. El registro formal le permite ser cortés y preciso sin añadir fórmulas largas que oculten lo que necesita saber.",
