  "explanation": "Register adaptation changes expression, not the truth of the message.",
  "spanish": "Clara debe informar de un cambio de horario a una amiga y a un centro cultural. A su amiga escribe una explicación cercana y propone hablar por teléfono. Al centro envía el número de reserva, la nueva disponibilidad y una solicitud de cambio. No cambia los hechos entre mensajes; cambia el modo de presentarlos según lo que cada destinatario necesita. Ana le pregunta si el mensaje formal debe ser más largo. Clara responde que no necesariamente: conviene incluir datos y una petición clara. Una fórmula cortés no sustituye esos elementos. Antes de enviar, revisa que la nueva fecha aparezca igual en ambos textos. Mantener el registro adecuado no significa esconder la información ni sonar distante por obligación. Significa facilitar una respuesta útil dentro de una relación diferente.",
