  "spanish": "Diego reclamó un cobro duplicado por una reserva. La empresa respondió que devolvería una cantidad, pero el mensaje no mostraba cómo la calculó. Diego comparó los dos cargos y pidió un desglose. La nueva respuesta confirmó que el primer cálculo era incompleto. Antes de dar el caso por cerrado, comprobó el importe y el plazo. Después envió un agradecimiento breve con una confirmación de lo acordado. No retiró el registro de la reclamación hasta recibir la devolución. Elena pensaba que pedir detalles después de una disculpa era desconfiar demasiado. Diego explicó que una disculpa y una solución verificable cumplen funciones distintas. La conversación terminó cuando la cantidad llegó y coincidió con el acuerdo. La cortesía no le impidió comprobar un resultado que afectaba a su dinero.",
