  "explanation": "Source attribution and scope prevent a summary from overstating the report.",
  "spanish": "Ana lee un titular que anuncia un gran cambio en el transporte. El texto cita un aumento de viajeros durante una semana. También recoge la opinión de una responsable que atribuye la subida al nuevo horario. Luis está a punto de resumirlo como una mejora permanente demostrada. Ana le recuerda que el dato cubre una semana y que la explicación pertenece a la responsable. Preparan un resumen con tres partes: la cifra observada, el periodo y la interpretación atribuida. No niegan la posibilidad de mejora. Evitan ampliar el alcance de la información más allá de lo publicado. Después buscan si hay resultados de otros meses. La actividad les permite transmitir una noticia interesante sin convertir un titular llamativo en una conclusión propia. El lector del resumen puede distinguir lo medido de lo que alguien cree que explica la medida.",
