  "type": "text",
  "mode": "listening",
  "prompt": "Explain the reason using a short English or Spanish response.",
  "promptEs": "¿Por qué revisa las palabras originales?",
  "englishHint": "Explain the reason using a short English or Spanish response.",
  "answer": "Para representar la postura completa.",
  "accepted": [
   "Para representar la postura completa.",
   "To represent the full position."
  ],
  "language": "en-or-es",
  "explanation": "A summary should retain the source’s qualification, not only one convenient fragment.",
  "spanish": "Clara entrevista a una vecina sobre una plaza renovada. La vecina dice que le gusta tener más bancos, aunque le preocupa el ruido por las noches. Al preparar un texto, Clara escribe primero que la vecina está en contra de la reforma. Elena le pide comprobar las palabras originales. La respuesta incluía una valoración positiva y una preocupación específica. Clara revisa el resumen: la vecina aprecia los bancos, pero pide atender el ruido. No elimina la crítica para hacer un texto favorable ni elimina el apoyo para crear una discusión. Mantiene el equilibrio que expresó la persona. También distingue una cita exacta de una paráfrasis. La versión final ocupa menos palabras, pero conserva la relación entre las ideas. Resumir no consiste en escoger una frase que confirme el enfoque del autor, sino en representar lo relevante de manera proporcionada.",
