  "spanish": "Diego compara una página de una empresa con comentarios de usuarios. La página dice que una devolución tarda pocos días. Algunos comentarios describen esperas largas. Ana observa que no saben cuántos clientes tuvieron cada experiencia ni cuándo se escribieron los comentarios. Eso no vuelve inútiles las opiniones, pero limita lo que pueden concluir. Diego escribe al servicio para preguntar por el plazo actual y las condiciones. Después resume las diferencias a Luis: una fuente presenta la política oficial y otras relatan casos individuales. No mezcla ambas como si midieran lo mismo. La respuesta del servicio confirma un plazo y explica qué documentación lo inicia. Diego decide guardar esa información para poder reclamar si hace falta. La comparación de fuentes produce una pregunta concreta en lugar de una confianza o desconfianza absoluta.",
