  "explanation": "Conditional possibilities should be compared with actual resources and constraints.",
  "spanish": "Luis quiere estudiar en otra ciudad, pero no puede pagar todos los gastos. Si tuviera una ayuda, podría hacerlo sin trabajar tantas horas. Clara le pregunta por otras condiciones: alojamiento, tiempo de estudio y contacto con su familia. Luis reconoce que el dinero no es el único factor. Busca información sobre ayudas reales y considera un curso más corto cerca de casa. No usa la hipótesis para concluir que solo existe una vida buena posible. Elena propone comparar qué aprendería con cada opción. El análisis distingue una alternativa deseada de una opción disponible. Luis termina con una solicitud de información y una fecha para revisar los resultados. Su deseo sigue siendo importante, pero ahora puede explicarlo junto con límites y próximos pasos.",
