  "type": "text",
  "mode": "listening",
  "prompt": "Give a short response about the speaker’s viewpoint.",
  "promptEs": "¿Qué utilidad tuvo la hipótesis?",
  "englishHint": "Give a short response about the speaker’s viewpoint.",
  "answer": "Abrir ideas y mostrar prioridades.",
  "accepted": [
   "Abrir ideas y mostrar prioridades.",
   "Opening ideas and revealing priorities."
  ],
  "language": "en-or-es",
  "explanation": "Hypothetical exploration and actual resource decisions are distinct stages.",
  "spanish": "El equipo tiene presupuesto para una actividad. Ana pregunta qué harían si pudieran gastar más. Algunos elegirían una excursión larga; otros prepararían dos talleres pequeños. La pregunta imaginada revela prioridades distintas, pero no aumenta el dinero disponible. Marta vuelve después a las opciones reales y propone decidir con el presupuesto actual. Luis sugiere una versión más corta de la excursión y Diego calcula materiales para un taller. Comparan qué beneficios conservaría cada adaptación y qué perdería. Nadie usa el deseo como argumento suficiente. Al final acuerdan una actividad pequeña y guardan las otras propuestas para otra ocasión. La conversación demuestra que una hipótesis puede abrir ideas, siempre que el grupo vuelva a las condiciones reales antes de comprometer recursos que no tiene.",
