  "language": "en-or-es",
  "explanation": "A successful partial change can guide, rather than end, further diagnosis.",
  "spanish": "Diego recibe quejas por la espera en el café. Piensa contratar otra persona inmediatamente. Clara observa que las colas aparecen sobre todo cuando todos piden en una sola mesa. Propone estudiar el proceso antes de asumir que falta personal. Ana anota tiempos en dos mañanas y descubre que una instrucción confusa provoca preguntas repetidas. Diego mejora el cartel y separa recogida y pedido. La espera baja, aunque los días con mucha gente siguen siendo difíciles. No usa la mejora para concluir que nunca necesitará ayuda. Compara los resultados y plantea una persona extra solo en ciertas horas. La solución evoluciona porque distingue la causa observada de una explicación inicial. Escuchar una objeción no frenó la acción; permitió escoger una medida más precisa y comprobar dónde seguía el problema.",
