  "type": "choice",
  "mode": "listening",
  "prompt": "Read the situation and choose the supported interpretation.",
  "promptEs": "¿Qué rechaza Elena?",
  "englishHint": "Read the situation and choose the supported interpretation.",
  "answer": "Que solo una experiencia pueda ser verdadera.",
  "options": [
   "La experiencia de Luis.",
   "La existencia de problemas.",
   "Que solo una experiencia pueda ser verdadera."
  ],
  "explanation": "Different experiences can be valid evidence with distinct scope.",
  "spanish": "Elena participa en una conversación sobre una actividad en línea. A ella le resultó cómoda porque evitó un viaje largo y pudo preguntar por escrito. Luis tuvo problemas de conexión y prefirió la sesión presencial. Al principio alguien pidió elegir cuál experiencia era la verdadera. Elena explicó que ambas podían serlo: describían condiciones diferentes. Desde su punto de vista, la herramienta amplió posibilidades, pero no necesariamente para todos. Luis reconoció la ventaja del viaje evitado y pidió una alternativa para conexiones débiles. Marta propuso separar satisfacción, acceso y calidad de participación. No podían medir las tres cosas con un solo comentario. El grupo decidió preguntar por cada aspecto en lugar de recoger únicamente una nota general. Elena reformuló su posición: apoya mantener la opción en línea siempre que se hagan visibles sus límites. Luis no necesitó negar su experiencia positiva para defender la suya. Al final la discusión pasó de buscar una única versión a comparar qué condiciones permiten que una opción sea útil. La próxima evaluación incluirá preguntas sobre acceso y sobre la posibilidad real de intervenir.",
