  "language": "en-or-es",
  "explanation": "Quantifiers must match evidence; silence does not automatically mean agreement.",
  "spanish": "Diego escribe un anuncio diciendo que todos los clientes prefieren el nuevo horario del café. Ana le pregunta qué información tiene. Diego ha recibido varios comentarios positivos, pero no ha hablado con quienes dejaron de venir. El horario también coincide con un cambio en los turnos del barrio. Diego comprende que su muestra no representa automáticamente a cada persona. Cambia la frase: varios clientes valoran la apertura temprana y quieren mantenerla. No elimina el entusiasmo; evita una afirmación que no puede sostener. Clara propone dejar un espacio para comentarios sobre la tarde, que ahora es más corta. Luis teme que mencionar límites debilite el anuncio. Ana explica que la precisión puede aumentar la confianza porque muestra qué se sabe y qué falta. Diego decide mantener la descripción concreta y preguntar por necesidades distintas. El objetivo ya no es defender la palabra todos, sino encontrar un horario que pueda explicar con honestidad. Después comparará los comentarios sin tratar el silencio de una persona como acuerdo automático.",
