  "type": "choice",
  "mode": "listening",
  "prompt": "Choose the implication supported by the passage.",
  "promptEs": "¿Qué no garantiza Marta?",
  "englishHint": "Choose the implication supported by the passage.",
  "answer": "Accesibilidad universal.",
  "options": [
   "Accesibilidad universal.",
   "La existencia de escaleras.",
   "Una alternativa parcial."
  ],
  "explanation": "Perspective-aware description gives actionable details instead of universal labels.",
  "spanish": "Marta propone un recorrido cultural que incluye escaleras. Para ella es corto y fácil porque conoce el barrio y camina deprisa. Clara le pide considerar a alguien que llega por primera vez o necesita un ritmo diferente. Marta no había pensado en esas condiciones. No abandona toda la ruta: identifica los tramos con dificultades y busca alternativas. Ana le sugiere describir distancia y descansos en lugar de usar solo la palabra fácil. Luis pregunta si ahora el recorrido es accesible a cualquier persona. Marta responde que no puede garantizarlo sin más información. Puede ofrecer datos para que cada visitante decida y consultar los puntos que desconoce. La revisión no transforma una perspectiva personal en la única legítima. La coloca junto a otras necesidades. Al final el anuncio evita una promesa universal e incluye una alternativa sin escaleras para una parte del camino. Marta aprende que matizar no equivale a renunciar al objetivo, sino a explicar mejor para quién y en qué condiciones funciona.",
