  "prompt": "Read the situation and choose the supported interpretation.",
  "promptEs": "¿Qué ocurrió antes del cambio de fecha?",
  "englishHint": "Read the situation and choose the supported interpretation.",
  "answer": "Ya habían preparado invitaciones.",
  "options": [
   "Ya habían preparado invitaciones.",
   "Se publicó el relato meses después.",
   "La exposición terminó."
  ],
  "explanation": "Narrative reflection can preserve success while identifying process limits.",
  "spanish": "Elena relata la preparación de una exposición varios meses después. Al principio recuerda una semana difícil porque la fecha cambió cuando ya habían preparado invitaciones. Luis recuerda que el grupo consiguió una sala mejor y que asistieron más personas de lo esperado. Antes del cambio, Elena había pedido a cada compañero una tarea, pero no fijó una forma de confirmar el resultado. Cuando faltó un material, pensó que nadie cumplía los acuerdos. Después descubrió que dos personas recibieron versiones distintas de la lista. Esa información modificó su reacción sin borrar el cansancio que sintió. En el relato distingue lo que sabía entonces de lo que sabe ahora. Dice que habría pedido una confirmación única antes de imprimir. No presenta esa alternativa como un hecho pasado. Ana señala que la exposición salió bien y pregunta si eso vuelve innecesaria la reflexión. Elena responde que un buen resultado puede convivir con un proceso que necesita mejora. Su narración termina con una decisión concreta para futuras actividades y no con una versión ideal donde todo estaba previsto.",
