  "language": "en-or-es",
  "explanation": "Extended narration can integrate intention, impact and hindsight.",
  "spanish": "Clara recuerda la primera actividad que organizó para vecinos. Llegó tarde porque estaba ayudando a una participante a encontrar el acceso sin escaleras. Dentro, algunas personas pensaron que olvidó la hora. Antes de salir, Clara había confirmado la ruta en una página antigua y descubrió una obra al llegar. Primero buscó una alternativa y después avisó al grupo. Al contar la experiencia años más tarde, no presenta su retraso como algo sin efecto: varias personas esperaron sin suficiente información. Tampoco acepta que la única explicación fuera desinterés. Relaciona el dato equivocado, la ayuda concreta y la comunicación tardía. Luis destaca que finalmente todos participaron. Clara valora ese resultado, pero dice que habría comprobado el acceso con el centro y avisado antes. El relato permite reconocer una intención útil y una mejora necesaria. La reflexión termina en dos acciones prácticas para la siguiente actividad, no en una defensa absoluta de todo lo que hizo.",
