  "explanation": "Preparation and consent make real-world practice more useful without guaranteeing identical outcomes.",
  "spanish": "El centro propone que un grupo practique español en el mercado. Diego ve una oportunidad para usar preguntas reales; Elena teme que pedir ayuda a comerciantes ocupados moleste. La profesora no descarta ninguna preocupación. Organiza primero una actividad en clase para preparar preguntas breves y después consulta qué puestos quieren participar. Algunos aceptan durante una hora tranquila y otros prefieren no hacerlo. El grupo respeta esa elección. En la visita, las conversaciones varían: una persona explica una receta y otra responde solo a una pregunta sobre precios. Ana cuenta que entendió menos de lo esperado, pero pudo pedir una repetición. Luis valora haber descubierto qué expresiones le faltaban. Al volver, no clasifican la experiencia como éxito total o fracaso. Comparan objetivos, condiciones y aprendizajes distintos. Elena reconoce que preparar el encuentro redujo la molestia posible. Diego admite que salir del aula no enseña automáticamente más. La profesora propone otra visita con preguntas mejor elegidas y agradecimientos claros. La práctica real complementa la preparación, y la reflexión posterior ayuda a convertir una conversación breve en un objetivo de aprendizaje.",
