  "englishHint": "Respond aloud to this writing scenario. Use connected ideas; the model is only one possible response.",
  "answer": "Una gestión en línea me evitó un viaje, pero la confirmación no era clara. Esa experiencia permite identificar un problema concreto; no demuestra que cualquier sistema digital funcione mal.\n\nMejoraría las instrucciones y mantendría una forma de pedir ayuda. Antes de cerrar la atención presencial, preguntaría quién la necesita y por qué. Evaluaría pasos concretos, no solo una opinión general sobre tecnología.",
