  "explanation": "Register adapts the form and relevant detail, not the truth of the message.",
  "spanish": "Ana necesita cambiar la hora de una reunión. A Luis le escribe: «¿Podemos quedar un poco más tarde? El tren llega a las seis». Al centro que organiza la actividad envía otro mensaje: explica la fecha, la hora prevista y el retraso del tren, y pregunta si sería posible incorporarse a las seis y media. No inventa una avería ni una urgencia para hacer la petición más convincente. Luis responde con una propuesta breve; el centro necesita consultar quién abrirá la puerta. Ana comprende que la diferencia no depende solo de palabras elegantes. Cada destinatario necesita información distinta para actuar. En el mensaje al centro añade su nombre y el grupo al que pertenece. En el mensaje a Luis esos datos resultarían innecesarios. Cuando recibe la confirmación, agradece a ambos la ayuda sin usar exactamente el mismo cierre. Después revisa los textos con Marta. Las dos comprueban que el motivo y la nueva hora coinciden. El registro cambió, pero la situación no. Una petición clara puede ser cercana o formal sin exagerar ni ocultar los datos que permiten responder.",
