  "type": "text",
  "mode": "listening",
  "prompt": "Explain the reason using a short English or Spanish response.",
  "promptEs": "¿Por qué aporta otro mensaje?",
  "englishHint": "Explain the reason using a short English or Spanish response.",
  "answer": "Prueba la cancelación dentro del plazo.",
  "accepted": [
   "Prueba la cancelación dentro del plazo.",
   "It shows cancellation before the deadline."
  ],
  "language": "en-or-es",
  "explanation": "A precise complaint distinguishes the observed error from an unsupported accusation.",
  "spanish": "Diego recibe una factura con dos entradas para un taller al que asistió una sola persona. Su primer borrador dice que el centro siempre cobra mal. Marta le pregunta si puede apoyar esa afirmación. Diego reconoce que solo conoce este caso y cambia el mensaje. Indica el número de factura, la fecha y la diferencia que observa. Pide que revisen el importe y adjunta la confirmación de una plaza. Mantiene un tono firme sin atribuir intención al error. Una empleada responde que el registro muestra dos reservas. Diego explica que canceló una antes del plazo y aporta el mensaje correspondiente. No trata la primera respuesta como un rechazo definitivo: añade el dato que faltaba. Al final el centro corrige la factura. Diego agradece la revisión y conserva los mensajes. Cuando cuenta el problema a Luis utiliza un tono más informal, pero mantiene la misma cronología. La reclamación funcionó porque permitió comprobar la discrepancia, no porque sonara más enfadada. Una petición formal puede defender un derecho y seguir siendo precisa, respetuosa y abierta a aclarar la información.",
