  "explanation": "The register supports an actionable request while respecting privacy and unconfirmed arrangements.",
  "spanish": "Elena prepara un correo para pedir a su responsable que cambie un turno. A una compañera ya le explicó que necesita acompañar a un familiar. En el correo formal no comparte detalles privados innecesarios. Indica qué turno solicita cambiar, propone una alternativa y pregunta si encaja con las necesidades del equipo. Luis le sugiere una fórmula muy larga llena de disculpas. Elena decide que esa versión oculta la petición principal. Mantiene un saludo adecuado y una explicación breve. La responsable responde que la alternativa dejaría una tarea sin cubrir. Elena propone otro intercambio después de consultar a su compañera. No presenta ese acuerdo como confirmado hasta recibir su permiso. Cuando finalmente lo tiene, envía un mensaje claro con ambas fechas. La responsable acepta y agradece que haya considerado el trabajo pendiente. Elena aprende que ser formal no significa sonar distante ni escribir mucho. Significa ayudar al destinatario a comprender una petición, sus razones y sus consecuencias. La cercanía con la compañera y el respeto a la responsable pueden coexistir sin cambiar los hechos ni revelar información que no hace falta.",
