  "language": "en-or-es",
  "explanation": "Preserve modal language and distinguish confirmed process from an unconfirmed outcome.",
  "spanish": "Ana lee que una ruta de autobús podría cambiar el mes siguiente. El artículo atribuye la información a un borrador y aclara que no hay una decisión final. Al compartirlo, Diego escribe que el autobús dejará de pasar por la plaza. Elena pregunta dónde se confirmó. Diego vuelve al texto y ve que convirtió una posibilidad en certeza. Corrige el mensaje y añade la fuente. Luis señala que una vecina oyó una fecha distinta, pero nadie sabe de dónde salió. El grupo conserva esa información como un comentario pendiente de comprobar, no como prueba de otro calendario. Ana consulta el anuncio oficial, que invita a enviar observaciones sobre dos opciones. Resume lo que sí está confirmado: existe una consulta y el plazo termina el viernes. Las rutas definitivas siguen abiertas. Después explica su preferencia por mantener la parada de la plaza y la identifica como opinión propia. El grupo puede discutir consecuencias sin inventar una decisión. La corrección no obliga a dejar de hablar del tema; permite hablar con un grado de certeza que corresponde a la información disponible.",
