  "type": "choice",
  "mode": "listening",
  "prompt": "Choose the implication supported by the passage.",
  "promptEs": "¿Qué conclusión tiene apoyo?",
  "englishHint": "Choose the implication supported by the passage.",
  "answer": "Hay señales positivas y problemas de claridad.",
  "options": [
   "La crítica elimina cualquier ventaja.",
   "Hay señales positivas y problemas de claridad.",
   "El éxito fue universal."
  ],
  "explanation": "Attribution and scope prevent a summary from overstating the evidence.",
  "spanish": "Marta prepara un informe sobre un taller. Un participante dijo que le ayudó a hablar con vecinos; otra persona señaló que necesitaba instrucciones más claras. El primer borrador resume que el taller funcionó bien. Ana pregunta para quién y en qué aspecto. Marta añade las voces por separado y aclara que no pidió una evaluación a todos. No afirmó que la actividad funcionara en todos los casos. Luis propone incluir también un comentario de una persona que se fue pronto, pero reconoce que solo lo escuchó de otro participante. En el informe identifica esa información como indirecta y evita presentarla como una declaración comprobada. El grupo distingue observaciones propias, opiniones recibidas y preguntas pendientes. Marta concluye que hay señales positivas y un problema de claridad que merece revisión. No convierte la crítica en rechazo de todo el taller ni el elogio en aprobación universal. Antes de publicar, consulta si puede citar los mensajes y ofrece resumirlos sin nombres. Relatar la experiencia de otros exige cuidar tanto el contenido como el permiso para compartirlo.",
