  "language": "en-or-es",
  "explanation": "Reported information requires a clear time reference and separation of intention from confirmed action.",
  "spanish": "Luis recibe el lunes un mensaje de Elena: «Mañana hablaré con recepción y después os diré qué opciones hay». El martes Ana pregunta si ya conocen las opciones. Luis va a copiar la frase sin indicar cuándo se escribió, pero Marta observa que mañana podría entenderse como miércoles. Luis resume que Elena dijo el lunes que hablaría con recepción el martes. Todavía no sabe si lo hizo. Conserva esa diferencia entre una intención anunciada y una acción confirmada. Más tarde Elena responde que habló con recepción, pero que falta comprobar una sala. El grupo actualiza el resumen sin borrar el mensaje anterior. Ana distingue ahora lo prometido, lo realizado y lo pendiente. Nadie necesita cambiar automáticamente cada tiempo verbal: necesitan mantener la referencia temporal y el sentido del mensaje. Luis añade fechas cuando el contexto podría confundir. Así el grupo evita planificar sobre una palabra relativa que ya no señala el mismo día. La reformulación resulta más larga que una copia, pero permite entender qué información cambió y qué pregunta sigue abierta.",
