  "explanation": "An unreal past condition describes an alternative rather than evidence of its certain outcome.",
  "spanish": "El grupo llegó al restaurante después de una visita y descubrió que no había mesas libres. Luis había pensado que, al ser temprano, podrían entrar sin reservar. Ana recordó que junto al restaurante se celebraba un encuentro que desconocían. Mientras buscaban otra opción, Luis dijo: «Si hubiéramos reservado antes, habríamos conseguido una mesa». Marta precisó que no podían saberlo con seguridad: quizá el local ya estaba lleno cuando planearon la salida. Reformularon la idea como una posibilidad razonable, no como un resultado demostrado. Encontraron otro café y cenaron más tarde. Al contar la experiencia, distinguieron la decisión real, las circunstancias conocidas después y la alternativa imaginada. No usaron el condicional para culparse por información que no tenían. El siguiente plan incluyó consultar disponibilidad y conservar una segunda opción. Ana añadió que reservar no elimina cualquier imprevisto. La reflexión fue útil porque produjo una mejora concreta sin prometer controlar todo. Imaginar un pasado distinto ayudó a revisar el proceso, aunque no permitió comprobar qué habría ocurrido en una situación que nunca llegó a existir.",
