  "explanation": "Real conditions, imagined resources and past alternatives have different roles in planning.",
  "spanish": "Marta prepara una salida para el sábado. Si el centro confirma el transporte el jueves, comprarán las entradas el viernes. Si no responde, harán una actividad cercana sin reserva. Diego propone esperar hasta el sábado, pero Ana explica que entonces quizá no queden entradas. El grupo compara consecuencias sin afirmar que una rama del plan ya ocurrió. Elena añade un escenario imaginado: con más presupuesto, contratarían un transporte propio. No lo presenta como una opción disponible ahora. Marta deja esa idea para otra ocasión y mantiene dos alternativas reales. El jueves llega una respuesta parcial: hay vehículo, pero falta confirmar quién conducirá. El grupo no interpreta esa noticia como confirmación completa. Pregunta por el dato pendiente y fija una hora límite para decidir. Cuando termina el plazo sin respuesta, elige la actividad cercana. Algunos sienten decepción, pero entienden la condición que acordaron. Al revisar el plan, no dicen que esperar habría garantizado transporte. Reconocen que podían haber esperado más, a costa de perder la alternativa. La decisión refleja una comparación de riesgos y límites, no una predicción perfecta de lo que habría pasado.",
