  "language": "en-or-es",
  "explanation": "Link an imagined past improvement to a real future plan without treating uncertainty as proof.",
  "spanish": "Ana envió una petición para preparar un taller, pero olvidó indicar qué tarea necesitaba. Recibió respuestas amables sin compromisos concretos. Cuando aclaró el mensaje, Elena pudo ayudar, aunque ya no quedaba tiempo para imprimir unas hojas. Ana reflexionó: si hubiera explicado la tarea antes, quizá habría recibido ayuda más útil. Mantiene quizá porque no sabe quién habría tenido tiempo. Luis señala otra condición: enviar un mensaje claro no obliga a nadie a aceptar. Ana está de acuerdo y no transforma su reflexión en una acusación al grupo. Para el siguiente taller prepara una lista breve con tarea, fecha y forma de responder. Es posible que algunas personas no hayan leído el nuevo mensaje todavía; por eso espera antes de interpretar el silencio. Si mañana recibe dos confirmaciones, repartirá la preparación. Si no, reducirá la actividad para poder hacerla sola. La experiencia conecta una alternativa pasada, una incertidumbre presente y un plan real. El objetivo no es controlar a los demás, sino comunicar mejor y elegir un tamaño de actividad que corresponda a los recursos confirmados.",
