  "answer": "Marta debe explicar al grupo por qué la exposición abrirá una semana más tarde. La sala había sido confirmada, pero una reparación obligó a cambiar el acceso. En el mensaje informal cuenta la secuencia, reconoce la decepción y propone usar el tiempo para revisar los textos. La revisión no consiste solo en corregir formas verbales: también comprueba el significado, el destinatario y las consecuencias de cada afirmación. Los dos textos permiten organizar el mismo proyecto sin crear versiones incompatibles de lo sucedido.",
