  "promptEs": "Explica en voz alta dos o tres partes sobre un proyecto o experiencia. Incluye hechos, perspectivas, una objeción, respuesta y próximo paso. Revisa qué puedes afirmar con certeza.",
  "englishHint": "Respond aloud to this writing scenario. Use connected ideas; the model is only one possible response.",
  "answer": "Organizamos un paseo para conocer el barrio. Habíamos preparado una ruta larga, pero la primera prueba mostró que algunas personas terminaban cansadas. Comparamos tiempos, descansos y posibilidades de conversar.\n\nAna defendía visitar el mercado; Luis daba prioridad a un recorrido accesible. Reconocimos ambas necesidades y probamos una ruta base con una extensión voluntaria. La objeción principal era el esfuerzo de reunir al grupo después. Respondimos con un punto de encuentro y una persona responsable.\n\nLa prueba resultó útil, aunque participaron pocas personas. No afirmaría que el plan sirve para cualquiera. Propongo revisar el acceso con otros participantes antes de repetirlo. También pediría comentarios a quienes no pudieron asistir. Si conseguimos apoyo, organizaremos otra prueba el próximo mes.",
